export function ErrorChart({
  data,
  current,
}: {
  data: Sweep;
  current: number;
}) {
  const width = 600,
    height = 160,
    left = 45,
    top = 15,
    pw = 535,
    ph = 111;
  const values = data.points.flatMap((p) => [p.train_mse, p.validation_mse]);
  const low =
    Math.min(...values.map((v) => Math.log10(Math.max(v, 1e-7)))) - 0.15;
  const high =
    Math.max(...values.map((v) => Math.log10(Math.max(v, 1e-7)))) + 0.15;
  const x = (degree: number) => left + ((degree - 1) / 14) * pw;
  const y = (value: number) =>
    top + ((high - Math.log10(Math.max(value, 1e-7))) / (high - low)) * ph;
  const path = (key: "train_mse" | "validation_mse") =>
    data.points
      .map((p, i) => `${i ? "L" : "M"}${x(p.degree)},${y(p[key])}`)
      .join(" ");
  return (
    <svg
      className="error-chart"
      viewBox={`0 0 ${width} ${height}`}
      role="img"
      aria-label="不同模型阶数的训练与验证误差，纵轴为对数尺度"
    >
      {[0, 0.5, 1].map((f) => (
        <g key={f}>
          <line
            x1={left}
            x2={left + pw}
            y1={top + f * ph}
            y2={top + f * ph}
            stroke="#e9ecf2"
          />
          <text
            x={left - 9}
            y={top + f * ph + 4}
            textAnchor="end"
            className="axis-text"
          >
            {Math.pow(10, high - f * (high - low)).toPrecision(1)}
          </text>
        </g>
      ))}
      <line
        x1={x(current)}
        x2={x(current)}
        y1={top}
        y2={top + ph}
        stroke="#b9bfea"
        strokeDasharray="4 4"
      />
      <path
        d={path("train_mse")}
        stroke="#359e94"
        strokeWidth="2"
        fill="none"
      />
      <path
        d={path("validation_mse")}
        stroke="#e29a6b"
        strokeWidth="2.5"
        fill="none"
      />
      {data.points.map((p) => (
        <g key={p.degree}>
          <circle
            cx={x(p.degree)}
            cy={y(p.validation_mse)}
            r={p.degree === current ? 4 : 2.5}
            fill="#e29a6b"
          />
          <text
            x={x(p.degree)}
            y={height - 11}
            textAnchor="middle"
            className="axis-text"
          >
            {p.degree}
          </text>
        </g>
      ))}
    </svg>
  );
}
"use client";
import { useEffect, useRef, useState } from "react";
import type { BenchResult, Learning, Prediction } from "@/lib/bench";
import { number } from "@/lib/bench";

function useWidth() {
  const ref = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(760);
  useEffect(() => {
    if (!ref.current) return;
    const observer = new ResizeObserver(([entry]) =>
      setWidth(Math.max(300, Math.round(entry.contentRect.width))),
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, []);
  return { ref, width };
}
function domain(values: number[]) {
  const minimum = Math.min(...values),
    maximum = Math.max(...values);
  const pad = Math.max((maximum - minimum) * 0.1, 0.01);
  return [minimum - pad, maximum + pad];
}
function tick(value: number) {
  return Math.abs(value) >= 1000
    ? value.toPrecision(3)
    : Number(value.toPrecision(3)).toString();
}

export function PredictionChart({
  result,
  mode,
  feature,
  showTraining,
}: {
  result: BenchResult;
  mode: "parity" | "residual" | "feature";
  feature: number;
  showTraining: boolean;
}) {
  const { ref, width } = useWidth();
  const height = width < 500 ? 285 : 340;
  const left = 55,
    right = 20,
    top = 20,
    bottom = 48;
  const [active, setActive] = useState<{
    point: Prediction;
    training: boolean;
  } | null>(null);
  useEffect(() => setActive(null), [result.fingerprint, mode, feature]);
  const points = [
    ...result.validation_predictions.map((point) => ({
      point,
      training: false,
    })),
    ...(showTraining
      ? result.training_predictions.map((point) => ({ point, training: true }))
      : []),
  ];
  const getX = (p: Prediction) =>
    mode === "parity"
      ? p.actual
      : mode === "residual"
        ? p.prediction
        : p.features[feature];
  const getY = (p: Prediction) =>
    mode === "residual"
      ? p.residual
      : mode === "feature"
        ? p.actual
        : p.prediction;
  let xd = domain(points.map((p) => getX(p.point))),
    yd = domain(points.map((p) => getY(p.point)));
  if (mode === "parity") {
    const limits = domain(
      points.flatMap((p) => [p.point.actual, p.point.prediction]),
    );
    xd = limits;
    yd = limits;
  }
  if (mode === "residual") {
    const max =
      Math.max(...points.map((p) => Math.abs(p.point.residual)), 0.1) * 1.15;
    yd = [-max, max];
  }
  const x = (value: number) =>
    left + ((value - xd[0]) / (xd[1] - xd[0])) * (width - left - right);
  const y = (value: number) =>
    top + ((yd[1] - value) / (yd[1] - yd[0])) * (height - top - bottom);
  const xLabel =
    mode === "parity"
      ? `真实值（${result.dataset.unit}）`
      : mode === "residual"
        ? `预测值（${result.dataset.unit}）`
        : result.dataset.features[feature];
  const yLabel =
    mode === "residual"
      ? "残差：真实−预测"
      : mode === "feature"
        ? result.dataset.target
        : "预测值";
  return (
    <div ref={ref} className="bench-chart">
      <svg
        viewBox={`0 0 ${width} ${height}`}
        role="img"
        aria-label={`${xLabel}与${yLabel}散点图`}
      >
        {[0, 0.25, 0.5, 0.75, 1].map((f) => {
          const xv = xd[0] + f * (xd[1] - xd[0]),
            yv = yd[0] + f * (yd[1] - yd[0]);
          return (
            <g key={f}>
              <line
                x1={x(xv)}
                x2={x(xv)}
                y1={top}
                y2={height - bottom}
                stroke="#eef1f7"
              />
              <line
                x1={left}
                x2={width - right}
                y1={y(yv)}
                y2={y(yv)}
                stroke="#e9edf5"
                strokeDasharray="3 5"
              />
              <text
                x={x(xv)}
                y={height - bottom + 20}
                textAnchor="middle"
                className="bench-axis"
              >
                {tick(xv)}
              </text>
              <text
                x={left - 10}
                y={y(yv) + 4}
                textAnchor="end"
                className="bench-axis"
              >
                {tick(yv)}
              </text>
            </g>
          );
        })}
        {mode === "parity" && (
          <line
            x1={x(xd[0])}
            y1={y(xd[0])}
            x2={x(xd[1])}
            y2={y(xd[1])}
            stroke="#aab3c7"
            strokeDasharray="5 5"
          />
        )}
        {mode === "residual" && (
          <line
            x1={left}
            x2={width - right}
            y1={y(0)}
            y2={y(0)}
            stroke="#a3afc7"
            strokeDasharray="5 5"
          />
        )}
        {points.map(({ point, training }) => (
          <circle
            key={`${training}-${point.row}`}
            cx={x(getX(point))}
            cy={y(getY(point))}
            r={width < 500 ? 3 : 3.6}
            fill={training ? "#31a39a" : "#7281dc"}
            fillOpacity={training ? 0.42 : 0.64}
            stroke="white"
            strokeWidth=".5"
            onMouseEnter={() => setActive({ point, training })}
            onClick={() => setActive({ point, training })}
          >
            <title>{`样本${point.row}：真实${number(point.actual)}，预测${number(point.prediction)}`}</title>
          </circle>
        ))}
        <text x={left} y="12" className="bench-axis-label">
